-- LF L37 isolated PostgreSQL policy19 fixture from read-only live row (2026-11-13).
-- Minimized slice: identical column names/data types, current row bytes and touch_updated_at.
-- Trigger fn_guard_input_parameter_provenance_v1 and FK targets NOT recreated: not FULL parity.
CREATE SCHEMA IF NOT EXISTS lf_ops;
CREATE TABLE lf_ops.politicas_seguridad(
 policy_code text NOT NULL, category text NOT NULL, description text NOT NULL,
 enforcement_level text NOT NULL,policy_config jsonb NOT NULL DEFAULT '{}'::jsonb,
 status text NOT NULL DEFAULT 'CANDIDATO',source_decision_id text,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 security_policy_id bigint NOT NULL PRIMARY KEY,source_decision_number bigint,
 parameter_provenance jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE OR REPLACE FUNCTION lf_ops.touch_updated_at() RETURNS trigger
 LANGUAGE plpgsql SET search_path TO 'pg_catalog','lf_ops' AS $fn$
 BEGIN NEW.updated_at:=now(); RETURN NEW; END;
$fn$;
CREATE TRIGGER trg_politicas_seguridad_touch_updated_at BEFORE UPDATE ON lf_ops.politicas_seguridad
 FOR EACH ROW EXECUTE FUNCTION lf_ops.touch_updated_at();
